1	//! Generation of the gear-shaped test polygon.
2	
3	use std::f64::consts::PI;
4	
5	/// Builds the gear outline: `n` teeth, alternating between a point on the unit
6	/// circle and a point at radius 0.7 halfway to the next tooth.
7	///
8	/// The returned polygon has a single ring, matching the C++ fixture.
9	pub fn gear_polygon(n: i32) -> Vec<Vec<[f64; 2]>> {
10	    let mut polygon: Vec<Vec<[f64; 2]>> = Vec::new();
11	    let mut gear: Vec<[f64; 2]> = Vec::new();
12	
13	    let mut i: i32 = 0;
14	    while i < n {
15	        let angle1 = 2.0 * PI * (i as f64) / (n as f64);
16	        let angle2 = 2.0 * PI * (i as f64 + 0.5) / (n as f64);
17	
18	        gear.push([angle1.cos(), angle1.sin()]);
19	        gear.push([0.7 * angle2.cos(), 0.7 * angle2.sin()]);
20	
21	        i += 1;
22	    }
23	
24	    polygon.push(gear);
25	    polygon
26	}
