1	//! Geometric predicates.
2	//!
3	//! Every expression here mirrors the operand order of the C++ original so the
4	//! floating point rounding is bit-for-bit identical: `a * b - c * d` is not
5	//! reassociated, and comparisons keep the same strict/non-strict boundaries.
6	
7	use super::node::Node;
8	
9	/// Signed double area of the triangle `p q r` (negative when counter-clockwise
10	/// in the reference's coordinate convention).
11	pub fn area(nodes: &[Node], p: usize, q: usize, r: usize) -> f64 {
12	    let (p, q, r) = (&nodes[p], &nodes[q], &nodes[r]);
13	    (q.y - p.y) * (r.x - q.x) - (q.x - p.x) * (r.y - q.y)
14	}
15	
16	/// Exact coordinate equality of two nodes.
17	pub fn equals(nodes: &[Node], p1: usize, p2: usize) -> bool {
18	    nodes[p1].x == nodes[p2].x && nodes[p1].y == nodes[p2].y
19	}
20	
21	/// Checks whether a point lies inside a triangle, boundary included.
22	#[allow(clippy::too_many_arguments)]
23	pub fn point_in_triangle(
24	    ax: f64,
25	    ay: f64,
26	    bx: f64,
27	    by: f64,
28	    cx: f64,
29	    cy: f64,
30	    px: f64,
31	    py: f64,
32	) -> bool {
33	    (cx - px) * (ay - py) - (ax - px) * (cy - py) >= 0.0
34	        && (ax - px) * (by - py) - (bx - px) * (ay - py) >= 0.0
35	        && (bx - px) * (cy - py) - (cx - px) * (by - py) >= 0.0
36	}
37	
38	pub fn sign(val: f64) -> i32 {
39	    if val > 0.0 {
40	        1
41	    } else if val < 0.0 {
42	        -1
43	    } else {
44	        0
45	    }
46	}
47	
48	/// For collinear points `p`, `q`, `r`, checks if `q` lies on segment `pr`.
49	pub fn on_segment(nodes: &[Node], p: usize, q: usize, r: usize) -> bool {
50	    let (p, q, r) = (&nodes[p], &nodes[q], &nodes[r]);
51	    q.x <= p.x.max(r.x) && q.x >= p.x.min(r.x) && q.y <= p.y.max(r.y) && q.y >= p.y.min(r.y)
52	}
53	
54	/// Checks if two segments `p1q1` and `p2q2` intersect.
55	pub fn intersects(nodes: &[Node], p1: usize, q1: usize, p2: usize, q2: usize) -> bool {
56	    let o1 = sign(area(nodes, p1, q1, p2));
57	    let o2 = sign(area(nodes, p1, q1, q2));
58	    let o3 = sign(area(nodes, p2, q2, p1));
59	    let o4 = sign(area(nodes, p2, q2, q1));
60	
61	    if o1 != o2 && o3 != o4 {
62	        return true; // general case
63	    }
64	
65	    // p1, q1 and p2 are collinear and p2 lies on p1q1
66	    if o1 == 0 && on_segment(nodes, p1, p2, q1) {
67	        return true;
68	    }
69	    // p1, q1 and q2 are collinear and q2 lies on p1q1
70	    if o2 == 0 && on_segment(nodes, p1, q2, q1) {
71	        return true;
72	    }
73	    // p2, q2 and p1 are collinear and p1 lies on p2q2
74	    if o3 == 0 && on_segment(nodes, p2, p1, q2) {
75	        return true;
76	    }
77	    // p2, q2 and q1 are collinear and q1 lies on p2q2
78	    if o4 == 0 && on_segment(nodes, p2, q1, q2) {
79	        return true;
80	    }
81	
82	    false
83	}
84	
85	/// Checks if a polygon diagonal `ab` is locally inside the polygon at `a`.
86	pub fn locally_inside(nodes: &[Node], a: usize, b: usize) -> bool {
87	    let (a_prev, a_next) = (nodes[a].prev, nodes[a].next);
88	    if area(nodes, a_prev, a, a_next) < 0.0 {
89	        area(nodes, a, b, a_next) >= 0.0 && area(nodes, a, a_prev, b) >= 0.0
90	    } else {
91	        area(nodes, a, b, a_prev) < 0.0 || area(nodes, a, a_next, b) < 0.0
92	    }
93	}
94	
95	/// Checks if the middle of the segment `ab` is inside the polygon.
96	pub fn middle_inside(nodes: &[Node], a: usize, b: usize) -> bool {
97	    let mut p = a;
98	    let mut inside = false;
99	    let px = (nodes[a].x + nodes[b].x) / 2.0;
100	    let py = (nodes[a].y + nodes[b].y) / 2.0;
101	    loop {
102	        let n = nodes[p].next;
103	        let (pn, nn) = (&nodes[p], &nodes[n]);
104	        if ((pn.y > py) != (nn.y > py))
105	            && nn.y != pn.y
106	            && (px < (nn.x - pn.x) * (py - pn.y) / (nn.y - pn.y) + pn.x)
107	        {
108	            inside = !inside;
109	        }
110	        p = n;
111	        if p == a {
112	            break;
113	        }
114	    }
115	
116	    inside
117	}
118	
119	/// Whether sector defined by node `m` contains sector defined by node `p`.
120	pub fn sector_contains_sector(nodes: &[Node], m: usize, p: usize) -> bool {
121	    area(nodes, nodes[m].prev, m, nodes[p].prev) < 0.0
122	        && area(nodes, nodes[p].next, m, nodes[m].next) < 0.0
123	}
