1	//! Command line argument handling.
2	
3	use std::ffi::OsString;
4	
5	/// Faithful reimplementation of C's `atoi`.
6	///
7	/// Skips leading whitespace, accepts an optional sign, consumes the leading run
8	/// of decimal digits and ignores the rest of the string. Values that overflow a
9	/// C `long` saturate at the `long` bounds (as `strtol` does) and are then
10	/// truncated to 32 bits, matching `atoi` on LP64 platforms — e.g. `4294967337`
11	/// yields `41`, and `99999999999999999999` yields `-1`.
12	pub fn atoi(s: &str) -> i32 {
13	    let bytes = s.as_bytes();
14	    let mut i = 0;
15	
16	    while i < bytes.len() && is_space(bytes[i]) {
17	        i += 1;
18	    }
19	
20	    let mut negative = false;
21	    if i < bytes.len() && (bytes[i] == b'+' || bytes[i] == b'-') {
22	        negative = bytes[i] == b'-';
23	        i += 1;
24	    }
25	
26	    let mut acc: i64 = 0;
27	    let mut saturated = false;
28	    while i < bytes.len() && bytes[i].is_ascii_digit() {
29	        if !saturated {
30	            let digit = (bytes[i] - b'0') as i64;
31	            match acc.checked_mul(10).and_then(|v| v.checked_add(digit)) {
32	                Some(v) => acc = v,
33	                None => saturated = true,
34	            }
35	        }
36	        i += 1;
37	    }
38	
39	    let value: i64 = if saturated {
40	        if negative {
41	            i64::MIN
42	        } else {
43	            i64::MAX
44	        }
45	    } else if negative {
46	        -acc
47	    } else {
48	        acc
49	    };
50	
51	    value as i32
52	}
53	
54	fn is_space(b: u8) -> bool {
55	    matches!(b, b' ' | b'\t' | b'\n' | 0x0b | 0x0c | b'\r')
56	}
57	
58	/// Reads the tooth count from the command line, defaulting to 11.
59	///
60	/// The C++ fixture does `int n = 11; if (argc > 1) n = std::atoi(argv[1]);`.
61	///
62	/// The iterator comes from `std::env::args_os()` rather than `std::env::args()`
63	/// because the latter panics on an argument that is not valid UTF-8, while the
64	/// C++ program happily runs `atoi` over the raw bytes. Lossy decoding is exactly
65	/// equivalent here: only bytes >= 0x80 are ever replaced, and `atoi` already
66	/// treats every such byte as a terminator, so the ASCII prefix that determines
67	/// the result is preserved untouched.
68	pub fn parse_n<I: Iterator<Item = OsString>>(args: I) -> i32 {
69	    let mut args = args;
70	    match args.nth(1) {
71	        Some(arg) => atoi(&arg.to_string_lossy()),
72	        None => 11,
73	    }
74	}
