     1	//! z-order (Morton) curve support used to accelerate ear checks on larger
     2	//! polygons.
     3	//!
     4	//! Coordinates are mapped into a non-negative 15 bit integer range relative to
     5	//! the polygon bounding box, then bit-interleaved. Morton codes are monotone
     6	//! with respect to coordinate dominance, so every point inside a bounding box
     7	//! has a code inside the code range of that box's corners — which is what makes
     8	//! the range-limited search in `is_ear_hashed` complete.
     9	
    10	/// z-order of a point given its coords and the size of the data bounding box.
    11	pub fn z_order(x_: f64, y_: f64, min_x: f64, min_y: f64, inv_size: f64) -> i32 {
    12	    // coords are transformed into non-negative 15-bit integer range
    13	    let mut x = ((x_ - min_x) * inv_size) as i32;
    14	    let mut y = ((y_ - min_y) * inv_size) as i32;
    15	
    16	    x = (x | (x << 8)) & 0x00FF00FF;
    17	    x = (x | (x << 4)) & 0x0F0F0F0F;
    18	    x = (x | (x << 2)) & 0x3333_3333;
    19	    x = (x | (x << 1)) & 0x5555_5555;
    20	
    21	    y = (y | (y << 8)) & 0x00FF00FF;
    22	    y = (y | (y << 4)) & 0x0F0F0F0F;
    23	    y = (y | (y << 2)) & 0x3333_3333;
    24	    y = (y | (y << 1)) & 0x5555_5555;
    25	
    26	    x | (y << 1)
    27	}
